import{_ as o,o as i,c as a,a3 as s}from"./chunks/framework.CMTNx0DQ.js";const p=JSON.parse('{"title":"Lucide is the icon set everywhere","description":"","frontmatter":{"status":"accepted","date":"2026-11-07T00:00:00.000Z"},"headers":[],"relativePath":"docs/adr/0024-lucide-is-the-icon-set.md","filePath":"docs/adr/0024-lucide-is-the-icon-set.md"}'),t={name:"docs/adr/0024-lucide-is-the-icon-set.md"};function c(n,e,d,r,l,h){return i(),a("div",null,[...e[0]||(e[0]=[s('<h1 id="lucide-is-the-icon-set-everywhere" tabindex="-1">Lucide is the icon set everywhere <a class="header-anchor" href="#lucide-is-the-icon-set-everywhere" aria-label="Permalink to &quot;Lucide is the icon set everywhere&quot;">​</a></h1><p>Every icon in Coach Poulpy comes from <a href="https://lucide.dev" target="_blank" rel="noreferrer">Lucide</a>: the websites, the web mockups and docs site (ADR 0023), the phone and tablet mockups, and the Android and iOS apps. One set means one drawing style, one stroke weight and one name for each action, whatever the platform.</p><h2 id="what-it-means" tabindex="-1">What it means <a class="header-anchor" href="#what-it-means" aria-label="Permalink to &quot;What it means&quot;">​</a></h2><ul><li>A new icon is taken from Lucide by its Lucide name (<code>calendar</code>, <code>chevron-left</code>, <code>circle-exclamation-point</code>), using the name Lucide lists first rather than one of its older aliases (<code>circle-alert</code>, <code>history</code>). A platform never draws its own icon for an action Lucide already has.</li><li>Every platform draws the same Lucide version: the one <code>web/ui</code> pins for <code>@lucide/vue</code>.</li><li>Vue uses <a href="https://lucide.dev/guide/packages/lucide-vue" target="_blank" rel="noreferrer"><code>@lucide/vue</code></a>, the official package (it replaced <code>lucide-vue-next</code>, now deprecated): <code>&lt;ChevronLeft class=&quot;size-5&quot; aria-hidden=&quot;true&quot; /&gt;</code>.</li><li>Web, phone and tablet mockups stay plain HTML (<a href="./0016-mockups-are-plain-html-in-the-repo">ADR 0016</a>): an icon is the Lucide SVG copied inline, with <code>data-lucide=&quot;&lt;name&gt;&quot;</code>. <code>design/check-mockups.mjs</code> fails CI when an icon has no name or is not drawn as that Lucide icon.</li><li>Android and iOS use no Lucide package. <code>design/icons/</code> keeps a copy of each Lucide SVG the product uses, taken unchanged from <code>lucide-static</code>, and <code>design/build-icons.mjs</code> writes them for the apps: a <code>Lucide</code> object of Compose <code>ImageVector</code>s on Android (<code>Lucide.ChevronLeft</code>), and template vector images in <code>Assets.xcassets/Lucide</code> with a <code>Lucide</code> enum and a <code>LucideIcon</code> view on iOS (<code>LucideIcon(.chevronLeft, size: 20)</code>, <code>Label(&quot;action.delete&quot;, lucide: .trash)</code>). <code>node design/build-icons.mjs --add &lt;name&gt;</code> copies a new icon in; CI runs the script with <code>--check</code>.</li><li>Icons keep Lucide&#39;s drawing: a 24 box and a 2 wide round stroke, scaled with the icon. The apps size them in points or dp like any icon (24 by default, 16 to 20 beside text).</li><li>Poulpy&#39;s drawings are not icons. They stay generated by <code>design/build-poulpy.mjs</code> (<a href="./0012-design-tokens-generated-from-one-file">ADR 0012</a>), and so are the body map figures.</li><li>Icon colour comes from the colour roles in the <a href="./../design-system#colour-roles">design system</a>, never a raw palette step. An error keeps its icon: crimson, with words.</li></ul><h2 id="why" tabindex="-1">Why <a class="header-anchor" href="#why" aria-label="Permalink to &quot;Why&quot;">​</a></h2><ul><li>A person who learns one icon meaning in the app finds the same one on the website and in the docs.</li><li>One set can be used across Vue, Compose and SwiftUI with the same names, so mockups, screens and sites can be compared directly.</li><li>Lucide is open source under the ISC licence for its code. Most of its icons come from Feather and are under the MIT licence, which both allow use in the app and sites (<a href="https://lucide.dev/license" target="_blank" rel="noreferrer">Lucide license</a>). <code>design/icons/LICENSE</code> is Lucide&#39;s licence, kept with the copies.</li><li>Lucide publishes no Compose or SwiftUI package, and lists none for them among its third-party packages (checked on <a href="https://lucide.dev/packages" target="_blank" rel="noreferrer">lucide.dev/packages</a> in November 2026). The community ports found were weighed against copying the SVGs: <ul><li><code>com.composables:icons-lucide</code> (<a href="https://github.com/composablehorizons/compose-icons" target="_blank" rel="noreferrer">composablehorizons/compose-icons</a>, MIT) last released in December 2025, eleven months and many Lucide releases behind; Lucide renames icons between releases, so its names already differ from <code>@lucide/vue</code>&#39;s.</li><li><code>io.github.thelacspace:lucide-compose</code> (Apache 2.0) has one maintainer, two stars and no release since May 2026.</li><li><a href="https://github.com/JakubMazur/lucide-icons-swift" target="_blank" rel="noreferrer"><code>JakubMazur/lucide-icons-swift</code></a> (ISC) follows Lucide&#39;s releases automatically, but ships all of Lucide&#39;s icons as <code>UIImage</code>s by id, with no SwiftUI view, and would be a second version to keep in step with the web.</li><li>Copying the SVGs keeps both apps on exactly the web&#39;s version and names, ships only the icons in use, adds no dependency, and is the same generator pattern as the theme, Poulpy and the body map (<a href="./0012-design-tokens-generated-from-one-file">ADR 0012</a>). Updating Lucide is raising <code>@lucide/vue</code> in <code>web/ui</code> and copying the icons again.</li></ul></li></ul><h2 id="consequences" tabindex="-1">Consequences <a class="header-anchor" href="#consequences" aria-label="Permalink to &quot;Consequences&quot;">​</a></h2><ul><li>The Android app no longer depends on <code>material-icons-extended</code>; iOS no longer uses SF Symbols for icons.</li><li>An SF Symbol scaled with the text around it; a Lucide image on iOS has a fixed size, so each place says its size.</li><li>A screen or mockup that needs an icon Lucide lacks says so in its PR. The fix is a new drawing in <code>design/</code> that matches Lucide&#39;s stroke, not a different set. The movement-pattern badges and the treadmill have no exact Lucide match today: they use the nearest Lucide icon (see the <a href="./../design-system#icons">design system</a>) until real exercise pictures replace the badges.</li></ul>',8)])])}const m=o(t,[["render",c]]);export{p as __pageData,m as default};
